// frontend/src/pages/MonitoringDashboard.js
// Live DB + NFS monitoring — CPU/mem/disk wave graphs + process list
// Grouped by environment: Live | Pre-Production | QA

import { useState, useEffect, useCallback, useRef } from 'react';
import { monitoringAPI, nfsAPI } from '../services/api';
import { Btn, Spinner, toast } from '../components/UI';
import {
  LineChart, Line, XAxis, YAxis, Tooltip,
  ResponsiveContainer, CartesianGrid, ReferenceLine
} from 'recharts';

// ── CONSTANTS ─────────────────────────────────────────────────────────────────
const ENV_META = {
  live:           { label:'Live / Production', color:'var(--bv-red)',    bg:'var(--bv-red-bg)',    border:'var(--bv-red)',    icon:'activity'       },
  pre_production: { label:'Pre-Production',    color:'var(--bv-amber)',  bg:'var(--bv-amber-bg)',  border:'var(--bv-amber)',  icon:'test-pipe'      },
  qa:             { label:'QA / Testing',      color:'var(--bv-blue)',   bg:'var(--bv-blue-dim)',  border:'var(--bv-blue)',   icon:'microscope'     },
  development:    { label:'Development',       color:'var(--bv-green)',  bg:'var(--bv-green-dim)', border:'var(--bv-green)',  icon:'code'           },
  other:          { label:'Other',             color:'var(--bv-txt3)',   bg:'var(--bv-bg4)',       border:'var(--bv-bd2)',    icon:'server'         },
};
const DB_COLORS = {
  mysql:      { label:'MySQL',      bg:'#1e3a1e', color:'#4ec94e' },
  postgresql: { label:'PostgreSQL', bg:'#1a2550', color:'#7ca8f8' },
  redis:      { label:'Redis',      bg:'#3d1a10', color:'#f85149' },
};
const NFS_ROLE_META = {
  primary:       { label:'Primary DC',    color:'var(--bv-green)',  icon:'device-floppy' },
  secondary:     { label:'Secondary DC',  color:'var(--bv-cyan)',   icon:'server-2'      },
  remote:        { label:'Remote',        color:'var(--bv-amber)',  icon:'building'      },
  live:          { label:'Live',          color:'var(--bv-red)',    icon:'activity'      },
  pre_production:{ label:'Pre-Prod',      color:'var(--bv-amber)',  icon:'test-pipe'     },
  qa:            { label:'QA',            color:'var(--bv-blue)',   icon:'microscope'    },
  other:         { label:'Other',         color:'var(--bv-txt3)',   icon:'server'        },
};

// ── SMALL COMPONENTS ──────────────────────────────────────────────────────────
function PctBar({ pct, height = 6 }) {
  const p = Math.min(pct || 0, 100);
  const c = p >= 90 ? 'var(--bv-red)' : p >= 75 ? 'var(--bv-amber)' : 'var(--bv-green)';
  return (
    <div style={{ width:'100%', height, background:'var(--bv-bg4)', borderRadius:height/2, overflow:'hidden' }}>
      <div style={{ height:'100%', width:`${p}%`, background:c, borderRadius:height/2, transition:'width .5s' }}/>
    </div>
  );
}

function MetricBadge({ label, value, unit = '%', warn = 80, crit = 90 }) {
  const v   = parseFloat(value) || 0;
  const col = v >= crit ? 'var(--bv-red)' : v >= warn ? 'var(--bv-amber)' : 'var(--bv-green)';
  return (
    <div style={{ textAlign:'center' }}>
      <div style={{ fontSize:10, color:'var(--bv-txt3)', textTransform:'uppercase',
        letterSpacing:'.06em', marginBottom:3, whiteSpace:'nowrap' }}>{label}</div>
      <div style={{ fontSize:18, fontWeight:600, color: value == null ? 'var(--bv-txt3)' : col, lineHeight:1 }}>
        {value == null ? '—' : `${v}${unit}`}
      </div>
    </div>
  );
}

function StatusDot({ status }) {
  const c = { online:'var(--bv-green)', warn:'var(--bv-amber)', critical:'var(--bv-red)', offline:'var(--bv-red)', ok:'var(--bv-green)' };
  const col = c[status] || 'var(--bv-txt3)';
  return (
    <span style={{ width:8, height:8, borderRadius:'50%', background:col, display:'inline-block',
      boxShadow: (status==='online'||status==='ok') ? `0 0 6px ${col}` : 'none' }}/>
  );
}

// ── WAVE GRAPH ────────────────────────────────────────────────────────────────
function WaveGraph({ data, dataKey, color, label, unit='%', maxY=100, refLine }) {
  const fmt = (v) => v == null ? '' : `${parseFloat(v).toFixed(1)}${unit}`;
  const fmtTime = (v) => {
    if (!v) return '';
    const d = new Date(v);
    return `${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;
  };
  return (
    <div>
      <div style={{ fontSize:10, color:'var(--bv-txt3)', textTransform:'uppercase',
        letterSpacing:'.07em', marginBottom:4, fontWeight:600 }}>{label}</div>
      <ResponsiveContainer width="100%" height={72}>
        <LineChart data={data} margin={{ top:4, right:4, bottom:0, left:0 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="var(--bv-bd)" vertical={false}/>
          {refLine && <ReferenceLine y={refLine} stroke="var(--bv-amber)" strokeDasharray="4 2" strokeWidth={1}/>}
          <XAxis dataKey="snapshot_at" hide tickFormatter={fmtTime} tick={{ fontSize:9 }}/>
          <YAxis domain={[0, maxY]} hide/>
          <Tooltip
            contentStyle={{ background:'var(--bv-bg2)', border:'1px solid var(--bv-bd)',
              borderRadius:6, fontSize:11 }}
            labelFormatter={v => fmtTime(v)}
            formatter={v => [fmt(v), label]}/>
          <Line type="monotone" dataKey={dataKey} stroke={color} strokeWidth={2}
            dot={false} activeDot={{ r:4, fill:color }} connectNulls/>
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
}

// ── DB SERVER CARD ─────────────────────────────────────────────────────────────
function DBServerCard({ server, onCollect, collecting }) {
  const [expanded, setExpanded] = useState(false);
  const [history,  setHistory]  = useState([]);
  const [loadingHistory, setLoadingHistory] = useState(false);
  const db   = DB_COLORS[server.db_type] || DB_COLORS.mysql;
  const snap = server; // latest snapshot fields joined

  const loadHistory = useCallback(async () => {
    setLoadingHistory(true);
    try { setHistory(await monitoringAPI.dbHistory(server.id, 60)); }
    catch {}
    finally { setLoadingHistory(false); }
  }, [server.id]);

  useEffect(() => {
    if (expanded && history.length === 0) loadHistory();
  }, [expanded, loadHistory, history.length]);

  // Auto-refresh history every 60s when expanded
  useEffect(() => {
    if (!expanded) return;
    const t = setInterval(loadHistory, 60000);
    return () => clearInterval(t);
  }, [expanded, loadHistory]);

  const hasStats   = snap.cpu_pct != null && snap.cpu_pct !== '' || snap.mem_pct != null && snap.mem_pct !== '';
  const lastSeen   = snap.snapshot_at
    ? new Date(snap.snapshot_at).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})
    : null;

  return (
    <div style={{ background:'var(--bv-card)', border:'1px solid var(--bv-bd)',
      borderRadius:11, overflow:'hidden', transition:'border-color .2s' }}>

      {/* Header row */}
      <div style={{ display:'flex', alignItems:'center', gap:10,
        padding:'11px 14px', cursor:'pointer',
        background: expanded ? 'var(--bv-hover)' : 'var(--bv-card)' }}
        onClick={() => setExpanded(e => !e)}>

        {/* DB type icon */}
        <div style={{ width:34, height:34, borderRadius:8, background:db.bg, flexShrink:0,
          display:'flex', alignItems:'center', justifyContent:'center',
          fontSize:11, fontWeight:700, color:db.color }}>{db.label[0]}</div>

        {/* Name + host */}
        <div style={{ flex:1, minWidth:0 }}>
          <div style={{ display:'flex', alignItems:'center', gap:7, flexWrap:'wrap' }}>
            <span style={{ fontSize:13, fontWeight:500, color:'var(--bv-txt)' }}>{server.name}</span>
            <span style={{ fontSize:10, padding:'1px 7px', borderRadius:8, fontWeight:600,
              background:db.bg, color:db.color }}>{db.label}</span>
            {lastSeen && <StatusDot status="ok"/>}
          </div>
          <div style={{ fontSize:11, color:'var(--bv-txt3)', marginTop:2 }}>
            <span style={{ fontFamily:'monospace', color:'var(--bv-cyan)' }}>{server.host}:{server.port}</span>
            {server.database_name && <span style={{ marginLeft:6 }}>· {server.database_name}</span>}
            {lastSeen && <span style={{ marginLeft:8, color:'var(--bv-txt3)' }}>Updated {lastSeen}</span>}
          </div>
        </div>

        {/* Quick metrics */}
        {hasStats ? (
          <div style={{ display:'flex', gap:16, flexShrink:0 }}>
            <MetricBadge label="CPU"  value={snap.cpu_pct != null ? parseFloat(snap.cpu_pct).toFixed(1) : null}/>
            <MetricBadge label="Mem"  value={snap.mem_pct != null ? parseFloat(snap.mem_pct).toFixed(1) : null}/>
            <MetricBadge label="Disk" value={snap.disk_pct}/>
            {snap.connections != null && (
              <div style={{ textAlign:'center' }}>
                <div style={{ fontSize:10, color:'var(--bv-txt3)', textTransform:'uppercase', letterSpacing:'.06em', marginBottom:3 }}>Conns</div>
                <div style={{ fontSize:18, fontWeight:600, color:'var(--bv-blue)' }}>{snap.connections}</div>
              </div>
            )}
          </div>
        ) : (
          <div style={{ fontSize:11, color:'var(--bv-txt3)', fontStyle:'italic' }}>
            {server.monitoring_enabled ? 'No data yet' : 'Monitoring disabled'}
          </div>
        )}

        {/* Actions */}
        <div style={{ display:'flex', gap:6, flexShrink:0 }} onClick={e=>e.stopPropagation()}>
          {server.monitoring_enabled && (
            <Btn variant="ghost" size="sm" icon="refresh" loading={collecting===server.id}
              onClick={() => onCollect(server.id)}>Collect</Btn>
          )}
          <i className={`ti ti-chevron-${expanded?'up':'down'}`}
            style={{ fontSize:14, color:'var(--bv-txt3)', cursor:'pointer', padding:4 }}/>
        </div>
      </div>

      {/* Expanded detail */}
      {expanded && (
        <div style={{ borderTop:'1px solid var(--bv-bd)', padding:'14px', background:'var(--bv-bg3)',
          display:'flex', flexDirection:'column', gap:14 }}>

          {!server.monitoring_enabled && (
            <div style={{ padding:'10px 14px', background:'var(--bv-amber-bg)', border:'1px solid var(--bv-amber)',
              borderRadius:8, fontSize:12, color:'var(--bv-amber)' }}>
              <i className="ti ti-info-circle" style={{ marginRight:6 }}/>
              SSH monitoring not enabled for this server.
              Go to <a href="/targets" style={{ color:'var(--bv-blue)' }}>DB Servers</a> → Edit → enable monitoring + set SSH credentials.
            </div>
          )}

          {/* Wave graphs */}
          {history.length > 0 ? (
            <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:14 }}>
              <WaveGraph data={history} dataKey="cpu_pct"  color="var(--bv-blue)"   label="CPU %"    refLine={80}/>
              <WaveGraph data={history} dataKey="mem_pct"  color="var(--bv-purple)" label="Memory %" refLine={80}/>
              <WaveGraph data={history} dataKey="disk_pct" color="var(--bv-amber)"  label="Disk %"   refLine={80}/>
              <WaveGraph data={history} dataKey="connections" color="var(--bv-cyan)" label="DB Connections" unit="" maxY={200}/>
            </div>
          ) : loadingHistory ? (
            <div style={{ display:'flex', justifyContent:'center', padding:20, gap:10, color:'var(--bv-txt3)' }}>
              <Spinner size={20}/> Loading history...
            </div>
          ) : (
            <div style={{ textAlign:'center', padding:20, color:'var(--bv-txt3)', fontSize:12 }}>
              No history yet — wave graphs appear after first collection
            </div>
          )}

          {/* Load average */}
          {(snap.load_avg_1 != null) && (
            <div style={{ display:'flex', gap:14, padding:'8px 12px', background:'var(--bv-card)',
              borderRadius:8, border:'1px solid var(--bv-bd)' }}>
              <span style={{ fontSize:11, color:'var(--bv-txt3)', marginRight:4 }}>Load avg:</span>
              {[['1m', snap.load_avg_1],['5m', snap.load_avg_5],['15m', snap.load_avg_15]].map(([l,v])=>(
                <span key={l} style={{ fontSize:12, color:'var(--bv-txt2)' }}>
                  <span style={{ fontSize:10, color:'var(--bv-txt3)', marginRight:3 }}>{l}</span>
                  <strong style={{ color: parseFloat(v) > 4 ? 'var(--bv-red)' : parseFloat(v) > 2 ? 'var(--bv-amber)' : 'var(--bv-txt)' }}>
                    {v != null ? parseFloat(v).toFixed(2) : '—'}
                  </strong>
                </span>
              ))}
              {snap.db_size_mb != null && (
                <span style={{ marginLeft:'auto', fontSize:11, color:'var(--bv-txt3)' }}>
                  DB size: <strong style={{ color:'var(--bv-txt2)' }}>
                    {parseFloat(snap.db_size_mb) >= 1024 ? `${(parseFloat(snap.db_size_mb)/1024).toFixed(1)} GB` : `${snap.db_size_mb} MB`}
                  </strong>
                </span>
              )}
            </div>
          )}

          {/* Process list */}
          {snap.process_list && snap.process_list.length > 0 && (
            <div>
              <div style={{ fontSize:10, fontWeight:600, color:'var(--bv-txt3)',
                textTransform:'uppercase', letterSpacing:'.07em', marginBottom:6 }}>
                Top processes (by CPU)
              </div>
              <table style={{ width:'100%', borderCollapse:'collapse', fontSize:11 }}>
                <thead><tr>
                  {['User','PID','CPU%','Mem%','Command'].map(h=>(
                    <th key={h} style={{ textAlign:'left', padding:'4px 8px', color:'var(--bv-txt3)',
                      fontWeight:600, borderBottom:'1px solid var(--bv-bd)', fontSize:10,
                      textTransform:'uppercase', letterSpacing:'.05em' }}>{h}</th>
                  ))}
                </tr></thead>
                <tbody>
                  {snap.process_list.slice(0,8).map((p,i) => (
                    <tr key={i} style={{ background: i%2===0 ? 'var(--bv-bg3)' : 'transparent' }}>
                      <td style={{ padding:'4px 8px', color:'var(--bv-txt3)' }}>{p.user}</td>
                      <td style={{ padding:'4px 8px', fontFamily:'monospace', color:'var(--bv-txt3)' }}>{p.pid}</td>
                      <td style={{ padding:'4px 8px', fontWeight:600,
                        color: parseFloat(p.cpu)>50?'var(--bv-red)':parseFloat(p.cpu)>20?'var(--bv-amber)':'var(--bv-txt)' }}>
                        {p.cpu}
                      </td>
                      <td style={{ padding:'4px 8px', color:'var(--bv-txt2)' }}>{p.mem}</td>
                      <td style={{ padding:'4px 8px', fontFamily:'monospace', color:'var(--bv-txt2)',
                        maxWidth:260, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>
                        {p.command}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// ── NFS SERVER CARD ────────────────────────────────────────────────────────────
function NFSCard({ server, onCheck, checking }) {
  const [expanded, setExpanded] = useState(false);
  const [history,  setHistory]  = useState([]);
  const pct    = parseFloat(server.disk_pct) || 0;
  const meta   = NFS_ROLE_META[server.role] || NFS_ROLE_META.other;
  const stCol  = pct>=90?'var(--bv-red)':pct>=80?'var(--bv-amber)':'var(--bv-green)';

  const loadHistory = useCallback(async () => {
    try { setHistory(await monitoringAPI.nfsHistory(server.id, 60)); } catch {}
  }, [server.id]);

  useEffect(() => { if (expanded) loadHistory(); }, [expanded, loadHistory]);

  return (
    <div style={{ background:'var(--bv-card)', border:`1px solid ${pct>=90?'var(--bv-red)':pct>=80?'var(--bv-amber)':'var(--bv-bd)'}`,
      borderRadius:11, overflow:'hidden' }}>
      <div style={{ display:'flex', alignItems:'center', gap:10, padding:'11px 14px',
        cursor:'pointer' }} onClick={() => setExpanded(e=>!e)}>
        <div style={{ width:34, height:34, borderRadius:8, background:'var(--bv-bg3)', flexShrink:0,
          display:'flex', alignItems:'center', justifyContent:'center' }}>
          <i className={`ti ti-${meta.icon}`} style={{ fontSize:18, color:meta.color }}/>
        </div>
        <div style={{ flex:1, minWidth:0 }}>
          <div style={{ display:'flex', alignItems:'center', gap:7, flexWrap:'wrap' }}>
            <span style={{ fontSize:13, fontWeight:500, color:'var(--bv-txt)' }}>{server.name}</span>
            <span style={{ fontSize:10, padding:'1px 7px', borderRadius:8, fontWeight:600,
              background:'var(--bv-bg3)', color:meta.color }}>{meta.label}</span>
            {server.status && <StatusDot status={server.status==='online'?'ok':server.status}/>}
          </div>
          <div style={{ fontSize:11, color:'var(--bv-txt3)', marginTop:2 }}>
            <span style={{ fontFamily:'monospace', color:'var(--bv-cyan)' }}>{server.host}</span>
            <span>:{server.export_path} → {server.mount_point}</span>
          </div>
        </div>
        <div style={{ flexShrink:0, textAlign:'right' }}>
          {server.disk_size ? (
            <>
              <div style={{ fontSize:11, color:'var(--bv-txt3)', marginBottom:3 }}>
                {server.disk_used} / {server.disk_size}
              </div>
              <div style={{ width:120 }}>
                <div style={{ display:'flex', justifyContent:'space-between', fontSize:11, marginBottom:2 }}>
                  <span style={{ color:'var(--bv-txt3)' }}>Disk</span>
                  <strong style={{ color:stCol }}>{pct}%</strong>
                </div>
                <PctBar pct={pct}/>
              </div>
            </>
          ) : <span style={{ fontSize:11, color:'var(--bv-txt3)', fontStyle:'italic' }}>Not checked</span>}
        </div>
        <div style={{ display:'flex', gap:6, flexShrink:0 }} onClick={e=>e.stopPropagation()}>
          <Btn variant="ghost" size="sm" icon="refresh" loading={checking===server.id}
            onClick={() => onCheck(server.id)}>Check</Btn>
          <i className={`ti ti-chevron-${expanded?'up':'down'}`}
            style={{ fontSize:14, color:'var(--bv-txt3)', cursor:'pointer', padding:4 }}/>
        </div>
      </div>

      {expanded && history.length > 0 && (
        <div style={{ borderTop:'1px solid var(--bv-bd)', padding:14, background:'var(--bv-bg3)' }}>
          <WaveGraph data={history} dataKey="disk_pct" color={stCol} label="Disk % (60 min)" refLine={80}/>
        </div>
      )}
    </div>
  );
}

// ── MAIN PAGE ─────────────────────────────────────────────────────────────────
export default function MonitoringDashboard() {
  const [dbGroups,    setDbGroups]    = useState({});
  const [nfsServers,  setNfsServers]  = useState([]);
  const [loading,     setLoading]     = useState(true);
  const [collecting,  setCollecting]  = useState(null);
  const [checkingNfs, setCheckingNfs] = useState(null);
  const [activeTab,   setActiveTab]   = useState('db'); // db | nfs
  const [collectingAll, setCollectingAll] = useState(false);
  const lastRefresh = useRef(null);

  const loadAll = useCallback(async () => {
    try {
      const [groups, nfs] = await Promise.all([
        monitoringAPI.dbGrouped(),
        nfsAPI.list(),
      ]);
      setDbGroups(groups);
      setNfsServers(nfs);
      lastRefresh.current = new Date();
    } catch(e) { toast(e.message, 'error'); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { loadAll(); }, [loadAll]);
  useEffect(() => {
    const t = setInterval(loadAll, 60000);
    return () => clearInterval(t);
  }, [loadAll]);

  async function handleCollect(id) {
    setCollecting(id);
    try {
      await monitoringAPI.dbCollect(id);
      await loadAll();
      toast('Collected');
    } catch(e) { toast(e.message, 'error'); }
    finally { setCollecting(null); }
  }

  async function handleCollectAll() {
    setCollectingAll(true);
    try { await monitoringAPI.dbCollectAll(); await loadAll(); toast('All targets collected'); }
    catch(e) { toast(e.message, 'error'); }
    finally { setCollectingAll(false); }
  }

  async function handleNfsCheck(id) {
    setCheckingNfs(id);
    try {
      const res = await nfsAPI.check(id);
      setNfsServers(p => p.map(s => s.id===id ? { ...s, ...res } : s));
      toast(`${res.name}: ${res.status}`);
    } catch(e) { toast(e.message, 'error'); }
    finally { setCheckingNfs(null); }
  }

  // Summary counts
  const allDb   = Object.values(dbGroups).flat();
  const dbTotal = allDb.length;
  const dbWithData = allDb.filter(s => s.cpu_pct != null).length;
  const nfsOnline  = nfsServers.filter(s => s.status==='online').length;
  const nfsWarn    = nfsServers.filter(s => s.status==='warn'||s.status==='critical').length;
  const envOrder   = ['live','pre_production','qa','development','other'];

  return (
    <div style={{ flex:1, display:'flex', flexDirection:'column', overflow:'hidden' }}>

      {/* Header */}
      <div style={{ padding:'14px 22px 0', borderBottom:'1px solid var(--bv-bd)',
        background:'var(--bv-bg2)', flexShrink:0 }}>
        <div style={{ display:'flex', alignItems:'flex-start', justifyContent:'space-between', marginBottom:12 }}>
          <div>
            <div style={{ fontSize:20, fontWeight:500, color:'var(--bv-txt)', display:'flex', alignItems:'center', gap:9 }}>
              <i className="ti ti-activity" style={{ color:'var(--bv-blue)', fontSize:22 }}/>
              Server Monitoring
            </div>
            <div style={{ fontSize:12, color:'var(--bv-txt2)', marginTop:3 }}>
              {dbTotal} DB servers · {nfsServers.length} NFS servers ·{' '}
              <span style={{ color:'var(--bv-green)' }}>{nfsOnline} NFS online</span>
              {nfsWarn>0 && <span style={{ color:'var(--bv-amber)' }}> · {nfsWarn} warn</span>}
              {lastRefresh.current && <span style={{ color:'var(--bv-txt3)', marginLeft:8 }}>
                Refreshed {lastRefresh.current.toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}
              </span>}
            </div>
          </div>
          <div style={{ display:'flex', gap:8 }}>
            {activeTab==='db' && (
              <Btn variant="ghost" icon="refresh" loading={collectingAll} onClick={handleCollectAll}>
                Collect All DB
              </Btn>
            )}
            <Btn variant="ghost" icon="refresh" onClick={loadAll}>Refresh</Btn>
          </div>
        </div>

        {/* Tabs */}
        <div style={{ display:'flex', gap:0 }}>
          {[
            { id:'db',  label:`DB Servers (${dbTotal})`,        icon:'database'    },
            { id:'nfs', label:`NFS Servers (${nfsServers.length})`, icon:'server-bolt' },
          ].map(tab => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id)}
              style={{ padding:'8px 18px', background:'none', border:'none', cursor:'pointer',
                fontSize:13, fontWeight: activeTab===tab.id ? 600 : 400,
                color: activeTab===tab.id ? 'var(--bv-blue)' : 'var(--bv-txt3)',
                borderBottom: activeTab===tab.id ? '2px solid var(--bv-blue)' : '2px solid transparent',
                display:'flex', alignItems:'center', gap:7, transition:'color .15s' }}>
              <i className={`ti ti-${tab.icon}`} style={{ fontSize:14 }}/>{tab.label}
            </button>
          ))}
        </div>
      </div>

      {/* Body */}
      <div style={{ flex:1, overflowY:'auto', padding:'16px 22px', display:'flex', flexDirection:'column', gap:14 }}>

        {loading ? (
          <div style={{ display:'flex', justifyContent:'center', padding:60, gap:12, color:'var(--bv-txt3)' }}>
            <Spinner size={28}/> Loading monitoring data...
          </div>
        ) : activeTab === 'db' ? (
          /* ── DB SERVERS TAB ─────────────────────────────── */
          <>
            {envOrder.filter(env => dbGroups[env]?.length > 0).map(env => {
              const meta    = ENV_META[env] || ENV_META.other;
              const servers = dbGroups[env] || [];
              return (
                <div key={env}>
                  {/* Environment header */}
                  <div style={{ display:'flex', alignItems:'center', gap:10, padding:'8px 12px',
                    background:meta.bg, border:`1px solid ${meta.border}`, borderRadius:9,
                    marginBottom:8 }}>
                    <i className={`ti ti-${meta.icon}`} style={{ fontSize:16, color:meta.color }}/>
                    <span style={{ fontSize:13, fontWeight:600, color:meta.color }}>{meta.label}</span>
                    <span style={{ fontSize:11, color:'var(--bv-txt3)' }}>
                      — {servers.length} server{servers.length!==1?'s':''}
                    </span>
                    <div style={{ flex:1 }}/>
                    {/* Quick stats for this env group */}
                    <span style={{ fontSize:11, color:'var(--bv-txt3)' }}>
                      MySQL: {servers.filter(s=>s.db_type==='mysql').length} ·{' '}
                      PostgreSQL: {servers.filter(s=>s.db_type==='postgresql').length}
                      {servers.filter(s=>s.db_type==='redis').length>0 &&
                        ` · Redis: ${servers.filter(s=>s.db_type==='redis').length}`}
                    </span>
                  </div>
                  <div style={{ display:'flex', flexDirection:'column', gap:8, marginBottom:16 }}>
                    {servers.map(s => (
                      <DBServerCard key={s.id} server={s}
                        onCollect={handleCollect} collecting={collecting}/>
                    ))}
                  </div>
                </div>
              );
            })}
            {Object.keys(dbGroups).length === 0 && (
              <div style={{ textAlign:'center', padding:60, color:'var(--bv-txt3)' }}>
                <i className="ti ti-database-off" style={{ fontSize:52, display:'block', marginBottom:14, color:'var(--bv-bd2)' }}/>
                <div style={{ fontSize:16, fontWeight:500, color:'var(--bv-txt2)', marginBottom:6 }}>No DB servers found</div>
                <div style={{ fontSize:13 }}>Add DB servers in <a href="/targets" style={{ color:'var(--bv-blue)' }}>DB Servers</a> page</div>
              </div>
            )}
            {/* Enable monitoring hint */}
            {dbWithData === 0 && dbTotal > 0 && (
              <div style={{ padding:'12px 16px', background:'var(--bv-blue-dim)',
                border:'1px solid var(--bv-blue)', borderRadius:9, fontSize:12, color:'var(--bv-txt2)' }}>
                <i className="ti ti-info-circle" style={{ marginRight:7, color:'var(--bv-blue)' }}/>
                <strong>Setup required:</strong> Go to{' '}
                <a href="/targets" style={{ color:'var(--bv-blue)' }}>DB Servers</a> → Edit each server →
                Enable monitoring → Add SSH user/password → then click "Collect All DB" above.
              </div>
            )}
          </>
        ) : (
          /* ── NFS SERVERS TAB ────────────────────────────── */
          <>
            {/* Group NFS by role */}
            {['live','pre_production','qa','primary','secondary','remote','other'].filter(role =>
              nfsServers.some(s => s.role===role)
            ).map(role => {
              const servers = nfsServers.filter(s => s.role===role);
              const meta    = NFS_ROLE_META[role] || NFS_ROLE_META.other;
              return (
                <div key={role}>
                  <div style={{ display:'flex', alignItems:'center', gap:8, marginBottom:8,
                    paddingBottom:6, borderBottom:'1px solid var(--bv-bd)' }}>
                    <i className={`ti ti-${meta.icon}`} style={{ fontSize:15, color:meta.color }}/>
                    <span style={{ fontSize:12, fontWeight:600, color:meta.color }}>{meta.label}</span>
                    <span style={{ fontSize:11, color:'var(--bv-txt3)' }}>— {servers.length} server{servers.length!==1?'s':''}</span>
                  </div>
                  <div style={{ display:'flex', flexDirection:'column', gap:8, marginBottom:16 }}>
                    {servers.map(s => (
                      <NFSCard key={s.id} server={s}
                        onCheck={handleNfsCheck} checking={checkingNfs}/>
                    ))}
                  </div>
                </div>
              );
            })}
            {nfsServers.length === 0 && (
              <div style={{ textAlign:'center', padding:60, color:'var(--bv-txt3)' }}>
                <i className="ti ti-server-off" style={{ fontSize:52, display:'block', marginBottom:14 }}/>
                <div style={{ fontSize:16, fontWeight:500, color:'var(--bv-txt2)' }}>No NFS servers</div>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}
